import org.jsoup.helper.UrlBuilder;
import org.junit.Test;
import org.jsoup.Connection.KeyVal;

import java.io.UnsupportedEncodingException;
import java.net.URL;
import java.net.URLEncoder;

import static org.junit.Assert.*;

public class UrlBuilderTest {

    @Test
    public void buildTest() throws UnsupportedEncodingException {
        URL inputUrl = new URL("http://www.example.com");
        UrlBuilder builder = new UrlBuilder(inputUrl);
        URL actualUrl = builder.build();
        assertEquals("http://www.example.com", actualUrl.toString());
    }

    @Test
    public void appendKeyValTest() throws UnsupportedEncodingException {
        URL inputUrl = new URL("http://www.example.com");
        UrlBuilder builder = new UrlBuilder(inputUrl);
        KeyVal kv = new KeyVal("key", "value");
        builder.appendKeyVal(kv);
        URL actualUrl = builder.build();
        assertEquals("http://www.example.com?key=value", actualUrl.toString());
    }

}
```

This test class contains 2 tests: `buildTest` and `appendKeyValTest`.

`buildTest` tests the `build` method. It creates a new `UrlBuilder` with an input URL, calls the `build` method, and checks if the returned URL is the same as the input URL.

`appendKeyValTest` tests the `appendKeyVal` method. It creates a new `UrlBuilder` with an input URL, appends a `KeyVal` object to the builder, and checks if the returned URL is correct after building.
